INSERT INTO public.products (id, slug, name, category, subcategory, description, price, compare_at_price, sku, stock, is_published, is_new_arrival, is_bestseller, is_featured, images, fabric, material, color, saree_length, blouse_piece, jewelry_dimensions, finish, care_instructions, rating, review_count, tags)
VALUES
('prod-001', 'royal-crimson-kadhwa-banarasi-silk-saree', 'Royal Crimson Kadhwa Banarasi Silk Saree', 'sarees', 'banarasi', 'A masterpiece woven by master artisans in Varanasi. Features exquisite Kadhwa gold and silver zari floral jaal with a regal meenakari border.', 24999, 32000, 'SWN-BAN-001', 8, true, true, true, true, '["https://images.unsplash.com/photo-1610030469983-98e550d6193c?auto=format&fit=crop&w=1200&q=80"]'::jsonb, 'Pure Katan Silk', NULL, 'Crimson Red & Antique Gold', '5.5 meters with 0.8 meter blouse piece', 'Unstitched running brocade blouse piece', NULL, 'Pure Handloom Zari Weave', 'Strictly dry clean only. Wrap in pure white muslin cloth.', 4.9, 38, '["Banarasi", "Pure Silk", "Bridal"]'::jsonb),
('prod-002', 'emerald-green-jangla-banarasi-silk-saree', 'Emerald Green Jangla Banarasi Silk Saree', 'sarees', 'banarasi', 'Imbued with royal heritage, this rich emerald green drape showcases intricate gold zari jangla vines interlaced with subtle floral motifs.', 21500, 28000, 'SWN-BAN-002', 5, true, false, true, true, '["https://images.unsplash.com/photo-1617627143750-d86bc21e42bb?auto=format&fit=crop&w=1200&q=80"]'::jsonb, 'Pure Mulberry Katan Silk', NULL, 'Emerald Green & Sona Rupa Zari', '5.5 meters with 0.8 meter blouse piece', 'Unstitched matching green silk blouse', NULL, 'Handwoven Jangla Weave', 'Dry clean only.', 4.8, 24, '["Banarasi", "Emerald"]'::jsonb),
('prod-021', 'heritage-kundan-pearl-chaandbaali-earrings', 'Heritage Kundan Pearl Chaandbaali Earrings', 'jewelry', 'earrings', 'Regal crescent moon chaandbaalis crafted with uncut Jadau Kundan stones, emerald cabochons, and cascading clusters of natural freshwater seed pearls.', 4999, 6800, 'SWN-JW-EAR-021', 22, true, true, true, true, '["https://images.unsplash.com/photo-1535632066927-ab7c9ab60908?auto=format&fit=crop&w=1200&q=80"]'::jsonb, NULL, 'Brass with 22k Gold Micron Plating, Kundan, Pearls', 'Antique Gold & Pearl White', NULL, NULL, 'Length: 7.5 cm, Width: 4.8 cm', '22k Gold Micron Plating', 'Store in airtight pouch. Avoid perfume contact.', 4.9, 64, '["Chaandbaali", "Kundan", "Pearls"]'::jsonb),
('prod-024', 'kundan-meenakari-bridal-hasli-choker', 'Kundan Meenakari Bridal Hasli Choker', 'jewelry', 'necklaces', 'An architectural Hasli rigid choker with intricate Jaipuri red and green Meenakari enameling on the reverse side, encrusted with glass kundan.', 8999, 12500, 'SWN-JW-NCK-024', 10, true, true, true, true, '["https://images.unsplash.com/photo-1599643478518-a784e5dc4c8f?auto=format&fit=crop&w=1200&q=80"]'::jsonb, NULL, 'High-grade Brass, Kundan, Hydro Emeralds, Pearls', 'Gold, Emerald Green & Pearl White', NULL, NULL, 'Choker Diameter: 14 cm, Adjustable zari dori drawstring', 'Hand-enameled Meenakari with 22k Gold Wash', 'Protect from moisture and cosmetics.', 5.0, 41, '["Choker", "Hasli", "Meenakari"]'::jsonb)
